import androidx.navigation.NavGraph.Companion.findStartDestination
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.currentBackStackEntryAsState
import androidx.navigation.compose.rememberNavController
import com.olasentra.staff.core.navigation.Route
import com.olasentra.staff.core.ui.components.OlasentraBottomBar
import com.olasentra.staff.feature.dashboard.navigation.dashboardGraph
import com.olasentra.staff.feature.gps.navigation.gpsGraph
import com.olasentra.staff.feature.messages.navigation.messagesGraph
import com.olasentra.staff.feature.profile.navigation.profileGraph
import com.olasentra.staff.feature.shifts.navigation.shiftsGraph

@Composable
fun OlasentraAppShell(
    onSignedOut: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val innerNavController = rememberNavController()
    val backStackEntry by innerNavController.currentBackStackEntryAsState()
    val currentRoute = backStackEntry?.destination?.route

    Scaffold(
        modifier = modifier,
        bottomBar = {
            OlasentraBottomBar(
                currentRoute = currentRoute,
                onNavigate = { route ->
                    innerNavController.navigate(route) {
                        popUpTo(innerNavController.graph.findStartDestination().id) {
                            saveState = true
                        }
                        launchSingleTop = true
                        restoreState = true
                    }
                },
            )
        },
    ) { innerPadding ->
        NavHost(
            navController = innerNavController,
            startDestination = Route.Dashboard.route,
            modifier = Modifier.padding(innerPadding),
        ) {
            dashboardGraph()
            shiftsGraph()
            gpsGraph()
            messagesGraph()
            profileGraph()
        }
    }
}

package com.olasentra.staff.navigation

import com.olasentra.staff.core.navigation.DeepLinkDestination
import javax.inject.Inject
import javax.inject.Singleton
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.asSharedFlow

@Singleton
class PendingDeepLinkBus @Inject constructor(
    private val deepLinkResolver: NotificationDeepLinkResolver,
) {
    private val _events = MutableSharedFlow<String>(extraBufferCapacity = 1)
    val events: SharedFlow<String> = _events.asSharedFlow()

    fun publishDestination(destination: DeepLinkDestination) {
        publishRoute(deepLinkResolver.routeForDestination(destination))
    }

    fun publishRoute(route: String) {
        _events.tryEmit(route)
    }
}

package com.olasentra.staff.sync

import android.content.Context
import androidx.hilt.work.HiltWorker
import androidx.work.Constraints
import androidx.work.CoroutineWorker
import androidx.work.ExistingPeriodicWorkPolicy
import androidx.work.NetworkType
import androidx.work.PeriodicWorkRequestBuilder
import androidx.work.WorkManager
import androidx.work.WorkerParameters
import com.olasentra.staff.domain.repository.AttendanceRepository
import dagger.assisted.Assisted
import dagger.assisted.AssistedInject
import java.util.concurrent.TimeUnit

@HiltWorker
class OfflineSyncWorker @AssistedInject constructor(
    @Assisted appContext: Context,
    @Assisted workerParams: WorkerParameters,
    private val attendanceRepository: AttendanceRepository,
) : CoroutineWorker(appContext, workerParams) {

    override suspend fun doWork(): Result {
        return attendanceRepository.syncPendingOfflineActions()
            .fold(
                onSuccess = { Result.success() },
                onFailure = { Result.retry() },
            )
    }

    companion object {
        private const val WORK_NAME = "olasentra_offline_sync"

        fun schedule(context: Context) {
            val constraints = Constraints.Builder()
                .setRequiredNetworkType(NetworkType.CONNECTED)
                .build()
            val request = PeriodicWorkRequestBuilder<OfflineSyncWorker>(15, TimeUnit.MINUTES)
                .setConstraints(constraints)
                .build()
            WorkManager.getInstance(context).enqueueUniquePeriodicWork(
                WORK_NAME,
                ExistingPeriodicWorkPolicy.KEEP,
                request,
            )
        }
    }
}

