import androidx.compose.runtime.LaunchedEffect
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.hilt.navigation.compose.hiltViewModel
import com.olasentra.staff.core.ui.theme.OlasentraColors

@Composable
fun SplashScreen(
    onNavigateToLogin: () -> Unit,
    onNavigateToMain: () -> Unit,
    modifier: Modifier = Modifier,
    viewModel: SplashViewModel = hiltViewModel(),
) {
    LaunchedEffect(viewModel) {
        viewModel.navigationEffect.collect { effect ->
            when (effect) {
                SplashViewModel.NavigationEffect.NavigateToLogin -> onNavigateToLogin()
                SplashViewModel.NavigationEffect.NavigateToMain -> onNavigateToMain()
            }
        }
    }

    Box(
        modifier = modifier.fillMaxSize(),
        contentAlignment = Alignment.Center,
    ) {
        Text(
            text = "Olasentra Staff",
            style = MaterialTheme.typography.headlineMedium,
            color = OlasentraColors.Accent,
        )
    }
}

package com.olasentra.staff.ui

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.olasentra.staff.core.security.TokenStorage
import com.olasentra.staff.core.util.DispatcherProvider
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject
import kotlinx.coroutines.flow.MutableSharedFlow
import kotlinx.coroutines.flow.SharedFlow
import kotlinx.coroutines.flow.asSharedFlow
import kotlinx.coroutines.launch

@HiltViewModel
class SplashViewModel @Inject constructor(
    private val tokenStorage: TokenStorage,
    private val dispatchers: DispatcherProvider,
) : ViewModel() {

    private val _navigationEffect = MutableSharedFlow<NavigationEffect>(extraBufferCapacity = 1)
    val navigationEffect: SharedFlow<NavigationEffect> = _navigationEffect.asSharedFlow()

    init {
        viewModelScope.launch(dispatchers.io) {
            val accessToken = tokenStorage.getAccessToken()
            val destination = if (!accessToken.isNullOrBlank()) {
                NavigationEffect.NavigateToMain
            } else {
                NavigationEffect.NavigateToLogin
            }
            _navigationEffect.emit(destination)
        }
    }

    enum class NavigationEffect {
        NavigateToLogin,
        NavigateToMain,
    }
}

