package com.olasentra.staff.core.network

import com.olasentra.staff.core.network.dto.ApiErrorResponse
import com.olasentra.staff.core.util.ApiResult
import com.squareup.moshi.Moshi
import java.io.IOException
import javax.inject.Inject
import javax.inject.Singleton
import retrofit2.HttpException

@Singleton
class ApiCallHandler @Inject constructor(
    private val moshi: Moshi,
) {
    suspend fun <T> safeApiCall(block: suspend () -> T): ApiResult<T> {
        return try {
            ApiResult.Success(block())
        } catch (exception: HttpException) {
            ApiResult.Error(
                message = parseHttpErrorMessage(exception),
                throwable = exception,
                code = exception.code(),
            )
        } catch (exception: IOException) {
            ApiResult.Error(
                message = exception.message ?: "Network error",
                throwable = exception,
            )
        } catch (exception: Exception) {
            ApiResult.Error(
                message = exception.message ?: "Unknown error",
                throwable = exception,
            )
        }
    }

    private fun parseHttpErrorMessage(exception: HttpException): String {
        val errorBody = exception.response()?.errorBody()?.string()
        if (errorBody.isNullOrBlank()) {
            return exception.message()
        }

        return runCatching {
            moshi.adapter(ApiErrorResponse::class.java).fromJson(errorBody)?.error
        }.getOrNull()?.takeIf { it.isNotBlank() } ?: exception.message()
    }
}

package com.olasentra.staff.core.network

import com.olasentra.staff.core.security.TokenStorage
import javax.inject.Inject
import javax.inject.Singleton
import kotlinx.coroutines.runBlocking
import okhttp3.Interceptor
import okhttp3.Response

@Singleton
class AuthInterceptor @Inject constructor(
    private val tokenStorage: TokenStorage,
) : Interceptor {

    override fun intercept(chain: Interceptor.Chain): Response {
        val original = chain.request()
        if (shouldSkipAuth(original.url.encodedPath)) {
            return chain.proceed(original)
        }

        val accessToken = runBlocking { tokenStorage.getAccessToken() }
        if (accessToken.isNullOrBlank()) {
            return chain.proceed(original)
        }

        val authenticated = original.newBuilder()
            .header("Authorization", "Bearer $accessToken")
            .build()

        return chain.proceed(authenticated)
    }

    private fun shouldSkipAuth(encodedPath: String): Boolean {
        return encodedPath.contains("/config") || encodedPath.contains("/auth/")
    }
}

