interface SessionEventPublisher {
    val sessionExpiredEvents: SharedFlow<Unit>

    fun publishSessionExpired()
}

@Singleton
class SessionEventPublisherImpl @Inject constructor() : SessionEventPublisher {

    private val _sessionExpiredEvents = MutableSharedFlow<Unit>(extraBufferCapacity = 1)
    override val sessionExpiredEvents: SharedFlow<Unit> = _sessionExpiredEvents.asSharedFlow()

    override fun publishSessionExpired() {
        _sessionExpiredEvents.tryEmit(Unit)
    }
}

package com.olasentra.staff.core.util

import timber.log.Timber

interface AppLogger {
    fun d(tag: String, message: String, throwable: Throwable? = null)

    fun i(tag: String, message: String, throwable: Throwable? = null)

    fun w(tag: String, message: String, throwable: Throwable? = null)

    fun e(tag: String, message: String, throwable: Throwable? = null)
}

object TimberAppLogger : AppLogger {
    override fun d(tag: String, message: String, throwable: Throwable?) {
        if (throwable != null) {
            Timber.tag(tag).d(throwable, message)
        } else {
            Timber.tag(tag).d(message)
        }
    }

    override fun i(tag: String, message: String, throwable: Throwable?) {
        if (throwable != null) {
            Timber.tag(tag).i(throwable, message)
        } else {
            Timber.tag(tag).i(message)
        }
    }

    override fun w(tag: String, message: String, throwable: Throwable?) {
        if (throwable != null) {
            Timber.tag(tag).w(throwable, message)
        } else {
            Timber.tag(tag).w(message)
        }
    }

    override fun e(tag: String, message: String, throwable: Throwable?) {
        if (throwable != null) {
            Timber.tag(tag).e(throwable, message)
        } else {
            Timber.tag(tag).e(message)
        }
    }
}

package com.olasentra.staff.core.util

sealed interface ApiResult<out T> {
    data class Success<T>(val data: T) : ApiResult<T>

    data class Error(
        val message: String,
        val throwable: Throwable? = null,
        val code: Int? = null,
    ) : ApiResult<Nothing>

    data object Loading : ApiResult<Nothing>
}

inline fun <T> ApiResult<T>.onSuccess(action: (T) -> Unit): ApiResult<T> {
    if (this is ApiResult.Success) {
        action(data)
    }
    return this
}

inline fun <T> ApiResult<T>.onError(action: (ApiResult.Error) -> Unit): ApiResult<T> {
    if (this is ApiResult.Error) {
        action(this)
    }
    return this
}

fun <T> ApiResult<T>.getOrNull(): T? = (this as? ApiResult.Success)?.data

fun <T> ApiResult<T>.isLoading(): Boolean = this is ApiResult.Loading

fun <T> ApiResult<T>.isSuccess(): Boolean = this is ApiResult.Success

fun <T> ApiResult<T>.isError(): Boolean = this is ApiResult.Error

