@OptIn(ExperimentalMaterial3Api::class, ExperimentalLayoutApi::class)
@Composable
fun NotificationsScreen(
    onOpenRoute: (String) -> Unit = {},
    onOpenShiftDetail: (Long) -> Unit = {},
    modifier: Modifier = Modifier,
    viewModel: NotificationsViewModel = hiltViewModel(),
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    val notifications = viewModel.filteredNotifications()

    Scaffold(
        modifier = modifier,
        topBar = {
            Column(modifier = Modifier.fillMaxWidth()) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 16.dp, vertical = 16.dp),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Text(
                        text = "Notifications",
                        style = MaterialTheme.typography.headlineSmall,
                        fontWeight = FontWeight.SemiBold,
                    )
                    TextButton(
                        onClick = viewModel::markAllRead,
                        enabled = !uiState.isUpdating && (uiState.overview?.unreadCount ?: 0) > 0,
                    ) {
                        Text(text = "Mark all read")
                    }
                }
                LastSyncBanner(
                    lastSyncedAtEpochMs = uiState.lastSyncedAtEpochMs,
                    isOfflineData = uiState.showOfflineBanner,
                )
            }
        },
    ) { innerPadding ->
        PullToRefreshBox(
            isRefreshing = uiState.isRefreshing,
            onRefresh = viewModel::refresh,
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding),
        ) {
            when {
                uiState.isInitialLoading -> LoadingState()
                uiState.overview == null && uiState.errorMessage != null -> ErrorState(uiState.errorMessage.orEmpty())
                else -> {
                    val overview = uiState.overview
                    LazyColumn(
                        modifier = Modifier.fillMaxSize(),
                        contentPadding = PaddingValues(16.dp),
                        verticalArrangement = Arrangement.spacedBy(12.dp),
                    ) {
                        item {
                            Text(
                                text = "${overview?.unreadCount ?: 0} unread",
                                style = MaterialTheme.typography.titleMedium,
                            )
                        }

                        val categories = overview?.categories.orEmpty()
                        if (categories.isNotEmpty()) {
                            item {
                                Text(
                                    text = "Categories",
                                    style = MaterialTheme.typography.labelLarge,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                                )
                                Spacer(modifier = Modifier.height(8.dp))
                                FlowRow(
                                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                                    verticalArrangement = Arrangement.spacedBy(8.dp),
                                ) {
                                    FilterChip(
                                        selected = uiState.selectedCategory == null,
                                        onClick = { viewModel.selectCategory(null) },
                                        label = { Text("All") },
                                    )
                                    categories.forEach { category ->
                                        CategoryChip(
                                            category = category,
                                            selected = uiState.selectedCategory == category.category,
                                            onClick = { viewModel.selectCategory(category.category) },
                                        )
                                    }
                                }
                            }
                        }

                        if (notifications.isEmpty()) {
                            item {
                                Text(
                                    text = "No notifications",
                                    style = MaterialTheme.typography.bodyMedium,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                                )
                            }
                        } else {
                            items(notifications, key = { it.id }) { notification ->
                                NotificationCard(
                                    notification = notification,
                                    onOpen = {
                                        viewModel.markRead(notification)
                                        handleNotificationAction(
                                            notification = notification,
                                            onOpenRoute = onOpenRoute,
                                            onOpenShiftDetail = onOpenShiftDetail,
                                        )
                                    },
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

private fun handleNotificationAction(
    notification: StaffNotification,
    onOpenRoute: (String) -> Unit,
    onOpenShiftDetail: (Long) -> Unit,
) {
    val relatedId = notification.relatedId
    relatedId?.let { id ->
        if (notification.category.startsWith("shift") || notification.type.contains("shift", ignoreCase = true)) {
            onOpenShiftDetail(id)
            return
        }
    }

    val actionUrl = notification.actionUrl?.lowercase().orEmpty()
    when {
        actionUrl.contains("shift") && relatedId != null -> onOpenShiftDetail(relatedId)
        actionUrl.contains("shift") -> onOpenRoute("shifts")
        actionUrl.contains("message") || actionUrl.contains("inbox") -> onOpenRoute("messages")
        actionUrl.contains("document") || actionUrl.contains("psa") -> onOpenRoute("documents")
        actionUrl.contains("availability") || actionUrl.contains("leave") -> onOpenRoute("availability")
        actionUrl.contains("check") || actionUrl.contains("attendance") -> onOpenRoute("check_in")
        notification.category == "message_received" -> onOpenRoute("messages")
        notification.category == "document_expiry" -> onOpenRoute("documents")
        notification.category == "check_in_reminder" -> onOpenRoute("check_in")
        notification.category.startsWith("shift") && relatedId != null -> onOpenShiftDetail(relatedId)
        notification.category.startsWith("shift") -> onOpenRoute("shifts")
        else -> Unit
    }
}

@Composable
private fun CategoryChip(
    category: NotificationCategory,
    selected: Boolean,
    onClick: () -> Unit,
    modifier: Modifier = Modifier,
) {
    FilterChip(
        selected = selected,
        onClick = onClick,
        modifier = modifier,
        label = { Text(category.label) },
    )
}

@Composable
private fun NotificationCard(
    notification: StaffNotification,
    onOpen: () -> Unit,
    modifier: Modifier = Modifier,
) {
    Card(
        modifier = modifier
            .fillMaxWidth()
            .clickable(onClick = onOpen),
    ) {
        Column(modifier = Modifier.padding(16.dp)) {
            Text(
                text = notification.categoryLabel,
                style = MaterialTheme.typography.labelMedium,
                color = MaterialTheme.colorScheme.secondary,
            )
            Spacer(modifier = Modifier.height(4.dp))
            Text(
                text = notification.title,
                style = MaterialTheme.typography.titleMedium,
                fontWeight = if (notification.isRead) FontWeight.Normal else FontWeight.SemiBold,
            )
            if (notification.body.isNotBlank()) {
                Spacer(modifier = Modifier.height(8.dp))
                Text(
                    text = notification.body,
                    style = MaterialTheme.typography.bodyMedium,
                    maxLines = 4,
                )
            }
            Spacer(modifier = Modifier.height(8.dp))
            Text(
                text = "${if (notification.isRead) "Read" else "Unread"} · ${notification.createdAt}",
                style = MaterialTheme.typography.labelMedium,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
            )
            val actionLabel = notification.actionLabel
            if (!actionLabel.isNullOrBlank()) {
                Spacer(modifier = Modifier.height(8.dp))
                OutlinedButton(onClick = onOpen, modifier = Modifier.fillMaxWidth()) {
                    Text(text = actionLabel)
                }
            }
        }
    }
}

@Composable
private fun LoadingState(modifier: Modifier = Modifier) {
    Column(
        modifier = modifier.fillMaxSize(),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center,
    ) {
        CircularProgressIndicator()
    }
}

@Composable
private fun ErrorState(message: String, modifier: Modifier = Modifier) {
    Column(
        modifier = modifier
            .fillMaxSize()
            .padding(24.dp),
        verticalArrangement = Arrangement.Center,
    ) {
        Text(text = message, color = MaterialTheme.colorScheme.error)
    }
}

package com.olasentra.staff.feature.notifications.ui

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.olasentra.staff.core.util.DispatcherProvider
import com.olasentra.staff.domain.model.NotificationsOverview
import com.olasentra.staff.domain.model.StaffNotification
import com.olasentra.staff.domain.repository.NotificationsRepository
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

@HiltViewModel
class NotificationsViewModel @Inject constructor(
    private val notificationsRepository: NotificationsRepository,
    private val dispatchers: DispatcherProvider,
) : ViewModel() {

    private val _uiState = MutableStateFlow(NotificationsUiState(isInitialLoading = true))
    val uiState: StateFlow<NotificationsUiState> = _uiState.asStateFlow()

    init {
        viewModelScope.launch(dispatchers.io) {
            notificationsRepository.observeNotifications().collect { resource ->
                _uiState.update { current ->
                    current.copy(
                        overview = resource.data,
                        lastSyncedAtEpochMs = resource.lastSyncedAtEpochMs,
                        isRefreshing = resource.isRefreshing,
                        errorMessage = if (resource.data == null) resource.errorMessage else null,
                        isInitialLoading = resource.data == null && resource.isRefreshing,
                        showOfflineBanner = resource.isFromCache && resource.errorMessage != null,
                    )
                }
            }
        }
        refresh()
    }

    fun refresh() {
        viewModelScope.launch(dispatchers.io) {
            notificationsRepository.refreshNotifications(_uiState.value.selectedCategory)
        }
    }

    fun selectCategory(category: String?) {
        _uiState.update { it.copy(selectedCategory = category) }
        refresh()
    }

    fun markRead(notification: StaffNotification) {
        if (notification.isRead) return
        viewModelScope.launch(dispatchers.io) {
            _uiState.update { it.copy(isUpdating = true) }
            notificationsRepository.markNotificationRead(notification.id)
            _uiState.update { it.copy(isUpdating = false) }
        }
    }

    fun markAllRead() {
        viewModelScope.launch(dispatchers.io) {
            _uiState.update { it.copy(isUpdating = true) }
            notificationsRepository.markAllNotificationsRead()
            _uiState.update { it.copy(isUpdating = false) }
        }
    }

    fun filteredNotifications(): List<StaffNotification> {
        val overview = _uiState.value.overview ?: return emptyList()
        val category = _uiState.value.selectedCategory
        if (category.isNullOrBlank()) return overview.notifications
        return overview.notifications.filter { it.category == category }
    }
}

data class NotificationsUiState(
    val overview: NotificationsOverview? = null,
    val selectedCategory: String? = null,
    val lastSyncedAtEpochMs: Long? = null,
    val isRefreshing: Boolean = false,
    val isInitialLoading: Boolean = false,
    val isUpdating: Boolean = false,
    val errorMessage: String? = null,
    val showOfflineBanner: Boolean = false,
)

