@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun AvailableEventsScreen(
    modifier: Modifier = Modifier,
    viewModel: AvailableEventsViewModel = hiltViewModel(),
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()

    Scaffold(
        modifier = modifier,
        topBar = {
            Column(modifier = Modifier.fillMaxWidth()) {
                PortalPageHeader(
                    title = "Available events",
                    subtitle = "Browse open opportunities and register interest.",
                )
                LastSyncBanner(
                    lastSyncedAtEpochMs = uiState.lastSyncedAtEpochMs,
                    isOfflineData = uiState.showOfflineBanner,
                )
            }
        },
    ) { innerPadding ->
        PullToRefreshBox(
            isRefreshing = uiState.isRefreshing,
            onRefresh = viewModel::refresh,
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding),
        ) {
            when {
                uiState.isInitialLoading -> {
                    Column(
                        modifier = Modifier.fillMaxSize(),
                        horizontalAlignment = Alignment.CenterHorizontally,
                        verticalArrangement = Arrangement.Center,
                    ) {
                        CircularProgressIndicator(color = OlasentraColors.Accent)
                    }
                }

                uiState.events.isEmpty() && uiState.errorMessage != null -> {
                    Column(
                        modifier = Modifier
                            .fillMaxSize()
                            .padding(24.dp),
                        verticalArrangement = Arrangement.Center,
                    ) {
                        Text(
                            text = uiState.errorMessage.orEmpty(),
                            color = MaterialTheme.colorScheme.error,
                        )
                    }
                }

                else -> {
                    LazyColumn(
                        modifier = Modifier.fillMaxSize(),
                        contentPadding = PaddingValues(bottom = 16.dp),
                        verticalArrangement = Arrangement.spacedBy(8.dp),
                    ) {
                        item {
                            PortalSectionTitle(title = "${uiState.events.size} open events")
                        }

                        if (uiState.events.isEmpty()) {
                            item {
                                Text(
                                    text = "No events are open for registration right now.",
                                    modifier = Modifier.padding(horizontal = 16.dp),
                                    style = MaterialTheme.typography.bodyMedium,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                                )
                            }
                        } else {
                            items(uiState.events, key = { it.eventId }) { event ->
                                AvailableEventCard(
                                    event = event,
                                    isApplying = uiState.applyingEventId == event.eventId,
                                    onApply = { viewModel.applyForEvent(event.eventId) },
                                )
                            }
                        }

                        uiState.actionMessage?.let { message ->
                            item {
                                Text(
                                    text = message,
                                    modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp),
                                    style = MaterialTheme.typography.bodyMedium,
                                    color = OlasentraColors.Accent,
                                )
                            }
                        }
                    }
                }
            }
        }
    }
